import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"先认识平台里的几个名词","description":"用一条温度监测的例子理解组织、工程、数据点、运行环境、节点、版本和部署。","frontmatter":{"title":"先认识平台里的几个名词","description":"用一条温度监测的例子理解组织、工程、数据点、运行环境、节点、版本和部署。","status":"reviewed","kind":"explanation"},"headers":[],"relativePath":"zh/concepts/getting-oriented.md","filePath":"zh/核心概念/先认识平台里的几个名词.md"}'),o={name:"zh/concepts/getting-oriented.md"};function n(i,t,s,l,h,c){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="先认识平台里的几个名词" tabindex="-1">先认识平台里的几个名词 <a class="header-anchor" href="#先认识平台里的几个名词" aria-label="Permalink to &quot;先认识平台里的几个名词&quot;">​</a></h1><p>第一次使用，不需要先学会数据库、容器或编程。先记住：<strong>人在组织里协作，在工程里做应用，把准备好的内容部署到运行环境中的合适节点上。</strong></p><p>本页只解释概念关系，例子不是已经配置好的业务，也不代表某种服务器组合已经通过部署验收。</p><h2 id="先认识这八个词" tabindex="-1">先认识这八个词 <a class="header-anchor" href="#先认识这八个词" aria-label="Permalink to &quot;先认识这八个词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>用普通话解释</th><th>不要误会成什么</th></tr></thead><tbody><tr><td>组织</td><td>一支团队在平台中的工作范围，管理自己的成员和工程</td><td>不是某一台服务器</td></tr><tr><td>工程</td><td>一个应用的工作包，把页面源码、数据配置和相关资料放在一起</td><td>新建工程不等于应用已经上线</td></tr><tr><td>数据点</td><td>给一项数据或一份结果起一个可引用的名字，方便页面、计算和报警使用</td><td>不一定是一只传感器，也不一定只有一个数字</td></tr><tr><td>开发环境</td><td>编写和检查工程的工作空间，提供 AI 助手、编辑器和预览等工具</td><td>不是正式运行环境</td></tr><tr><td>运行环境</td><td>在运维中安排工程运行资源、节点和基础服务的范围</td><td>创建环境名称不会凭空增加服务器</td></tr><tr><td>节点</td><td>平台登记的一台实际服务器或虚拟机，可按类型和资格承担相应任务</td><td>不是工程页面上的一个图标，也不是一个数据点</td></tr><tr><td>工程版本</td><td>把某个阶段的工程内容固定下来，便于选择、部署与追溯</td><td>不是数据备份，也不等于平台产品的 v1.0</td></tr><tr><td>部署</td><td>把选定的工程内容安排到目标环境及节点上运行</td><td>保存文件或打开预览不等于部署</td></tr></tbody></table><h2 id="用-看温度、超温提醒-串起来" tabindex="-1">用“看温度、超温提醒”串起来 <a class="header-anchor" href="#用-看温度、超温提醒-串起来" aria-label="Permalink to &quot;用“看温度、超温提醒”串起来&quot;">​</a></h2><p>假设团队想做一个温度监测应用：</p><ol><li>在自己的<strong>组织</strong>里新建一个<strong>工程</strong>。</li><li>配好实际数据来源，把温度作为一个<strong>数据点</strong>，供页面和规则引用。</li><li>在<strong>开发环境</strong>中做好页面，配置计算和报警，检查效果。</li><li>准备一份<strong>工程版本</strong>。</li><li>选择合适的<strong>运行环境</strong>与具备条件的<strong>节点</strong>，创建<strong>部署</strong>。</li><li>工程用户从实际运行地址打开应用，查看数据并使用业务功能。</li></ol><p>配置报警、发送通知、保存历史等仍需分别设置和验证，不会只因这几个对象已经存在就全部完成。</p><h2 id="工程、环境和节点不是一对一" tabindex="-1">工程、环境和节点不是一对一 <a class="header-anchor" href="#工程、环境和节点不是一对一" aria-label="Permalink to &quot;工程、环境和节点不是一对一&quot;">​</a></h2><p>可以这样理解它们之间的分工：</p><ul><li><strong>工程</strong>回答“要运行哪个应用、包含什么内容”。</li><li><strong>版本</strong>回答“采用这个应用的哪一份内容”。</li><li><strong>运行环境</strong>回答“在哪个运行范围里安排资源和访问”。</li><li><strong>节点</strong>回答“由哪些实际服务器承担具体任务”。</li><li><strong>部署</strong>把这些选择联系起来。</li></ul><p>一个运行环境可以面向多个工程安排部署，一台节点也可能承担不止一个服务；具体放置、权限和支持范围以实际配置及交付条件为准，不能据此推定无限共享或高可用。</p><h2 id="再分清两类用户" tabindex="-1">再分清两类用户 <a class="header-anchor" href="#再分清两类用户" aria-label="Permalink to &quot;再分清两类用户&quot;">​</a></h2><p><strong>组织账号</strong>用于登录平台工作台，负责开发、配置或运维。<strong>工程用户</strong>用于工程页面自己的登录与数据权限。</p><p>给组织账号分配“工程人员”，不等于自动创建了工程页面的登录用户；创建工程用户，也不会自动给它平台管理权限。详见<a href="/induframe-docs/zh/concepts/access.html">入口与账号</a>。</p><h2 id="刚开始按什么顺序读" tabindex="-1">刚开始按什么顺序读 <a class="header-anchor" href="#刚开始按什么顺序读" aria-label="Permalink to &quot;刚开始按什么顺序读&quot;">​</a></h2><ul><li>想知道一个温度值怎样被使用：<a href="/induframe-docs/zh/concepts/datapoints.html">什么是数据点</a>。</li><li>不清楚服务器、环境和部署的关系：<a href="/induframe-docs/zh/concepts/environments-and-nodes.html">什么是运行环境和节点</a>。</li><li>遇到 SQL、API Key、触发、死区等词：<a href="/induframe-docs/zh/reference/glossary.html">常用术语解释</a>。</li><li>已理解概念，准备操作：<a href="/induframe-docs/zh/start/first-project.html">创建第一个工程</a>。</li></ul>',18)])])}const _=r(o,[["render",n]]);export{p as __pageData,_ as default};
